 int xMin = Mathf.FloorToInt(pos.x - radius);
int xMax = Mathf.CeilToInt(pos.x + radius);
int xCenter = xMin + (xMax - xMin) / 2;
int yMin = Mathf.FloorToInt(pos.y - radius);
